program Loop71 implements ISolver {
    type Input = quantity;
    type Output = quantity;

    storage {
        iterations_run: mutable u64 = 0;
        last_total: mutable u64 = 0;
    }

    public function constructor() {
        assign iterations_run = 0;
        assign last_total = 0;
    }

    public function parse(raw: str): Input { return raw; }

    public function solve(input: Input): Output {
        create total : quantity;
        assign total = 0;
        create count : quantity;
        assign count = 8;
        store count, "loop_count";
        create step_amt : quantity;
        assign step_amt = 2;
        while (count > 0) {
            add total, step_amt;
            sub count, 1;
            add iterations_run, 1;
        }
